// Valida el formato de la acción: <accion>_<uuid>. «editreply» y «objectreply» los arma el router cuando el aprobador responde al mensaje que pide el nuevo caption o la objeción
const i = $input.first().json;
const chatId = String(i.chat_id ?? '').trim();
if (!/^-?\d{1,20}$/.test(chatId)) throw new Error('validation: chat_id no es numérico');
const m = String(i.callback_data ?? '').match(/^(approve|edit|regenerate|discard|editreply|object|objectreply|resolve|reopen)_([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/i);
if (!m) throw new Error('validation: callback_data con formato inesperado');
const replyText = String(i.reply_text ?? '').trim();
if (replyText.length > 2000) throw new Error('validation: reply_text supera 2000 caracteres');
// Quién pulsó (T-0035): id numérico de Telegram o null, nombre recortado
const actorId = /^\d{1,15}$/.test(String(i.actor_id ?? '')) ? String(i.actor_id) : '';
const actorName = String(i.actor_name ?? '').trim().slice(0, 200);
return [{ json: { action: m[1].toLowerCase(), content_item_id: m[2].toLowerCase(), chat_id: chatId, callback_query_id: String(i.callback_query_id ?? '').slice(0, 128),
  message_id: Number.isSafeInteger(Number(i.message_id)) ? Number(i.message_id) : 0, reply_text: replyText, actor_id: actorId, actor_name: actorName } }];

const tg = (method, body) => this.helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/${method}`, body, json: true, timeout: 30000 });
// Quita el relojito del botón de inmediato: regenerar tarda más de un minuto. Si falla no bloquea la acción
const e = $input.first().json;
if (e.callback_query_id) { try { await tg('answerCallbackQuery', { callback_query_id: e.callback_query_id, text: 'Procesando…' }); } catch (err) { /* no bloquea */ } }
return [{ json: e }];

const tg = (method, body) => this.helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/${method}`, body, json: true, timeout: 30000 });
// Aplica la acción sobre content_items. Cada cambio es condicional al estado actual: un botón repetido o viejo no pisa nada.
// Cada acción, aplicada o ignorada, deja una fila en review_actions con quién la hizo (T-0035)
const e = $input.first().json;
const base = `${$env.SUPABASE_URL}/rest/v1`;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const headers = { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json', Prefer: 'return=representation' };
const get = (qs) => this.helpers.httpRequest({ method: 'GET', url: `${base}/content_items`, headers, qs, json: true, timeout: 30000 });
const patch = (filter, body) => this.helpers.httpRequest({ method: 'PATCH', url: `${base}/content_items?${filter}`, headers, body, json: true, timeout: 30000 });
const done = (text, extra = {}) => [{ json: { then: 'none', text, changed: false, content_item_id: e.content_item_id, ...extra } }];
const id = e.content_item_id;

const run = async () => {

const [item] = await get({ select: 'id,status,asset_type,raw_asset_url,notes', id: `eq.${id}` });
if (!item) return done('⚠️ No encontré ese contenido; puede que ya se haya borrado.', { missing: true });
const stale = () => done(`ℹ️ Este contenido ya está en estado «${item.status}»: no hice cambios.`, { reason: `estado actual: ${item.status}` });
const allowed = { approve: ['ready_for_review'], edit: ['ready_for_review'], editreply: ['ready_for_review'], object: ['ready_for_review'], objectreply: ['ready_for_review'], resolve: ['ready_for_review'], reopen: ['stalled'], regenerate: ['ready_for_review', 'error'], discard: ['ready_for_review', 'error', 'stalled'] }[e.action];
if (!allowed.includes(item.status)) return stale();
const filter = `id=eq.${id}&status=in.(${allowed.join(',')})`;

// Objeción abierta = la última acción aplicada entre objectreply y resolve es objectreply (T-0039)
const openObjection = async () => {
  const [last] = await this.helpers.httpRequest({ method: 'GET', url: `${base}/review_actions`, headers, json: true, timeout: 30000,
    qs: { select: 'action,actor_name,detail', content_item_id: `eq.${id}`, outcome: 'eq.applied', action: 'in.(objectreply,resolve)', order: 'id.desc', limit: '1' } });
  return last?.action === 'objectreply' ? last : null;
};

if (e.action === 'approve') {
  const ob = await openObjection();
  if (ob) return done(`🚫 No se puede aprobar: hay una objeción abierta${ob.actor_name ? ` de ${ob.actor_name}` : ''}: «${String(ob.detail ?? '').slice(0, 300)}». Cuando se resuelva, toca «Resolver objeción» y vuelve a aprobar.`, { reason: 'objeción abierta' });
  const rows = await patch(filter, { status: 'approved', approved_by: 'telegram' });
  return rows.length ? done('✅ Contenido aprobado.', { changed: true }) : stale();
}
if (e.action === 'object') {
  // El router distingue esta respuesta de la de «Editar» por el 💬 con que empieza el mensaje
  await tg('sendMessage', { chat_id: e.chat_id, text: `💬 Escribe tu objeción respondiendo a este mensaje.\n\nContenido: ${id}`,
    reply_markup: { force_reply: true, input_field_placeholder: 'Tu objeción' } });
  return done(null, { prompted: true });
}
if (e.action === 'objectreply') {
  if (e.reply_text.length < 1) return done('⚠️ La objeción no puede estar vacía. Vuelve a tocar «Objetar».', { reason: 'objeción vacía' });
  // Solo se guarda como dato en review_actions; la aprobación queda bloqueada hasta que alguien la resuelva
  return done(`💬 Objeción registrada${e.actor_name ? ` de ${e.actor_name}` : ''}. La aprobación queda bloqueada hasta que alguien toque «Resolver objeción».`, { changed: true });
}
if (e.action === 'resolve') {
  if (!(await openObjection())) return done('ℹ️ No hay objeciones abiertas en este contenido.', { reason: 'sin objeción abierta' });
  return done(`✔️ Objeción resuelta${e.actor_name ? ` por ${e.actor_name}` : ''}. Ya se puede aprobar.`, { changed: true });
}
if (e.action === 'reopen') {
  // Una pieza sin decisión a las 48 h quedó en stalled (WF22): se reabre y se vuelve a mandar la propuesta, lo que reinicia los plazos
  const rows = await patch(filter, { status: 'ready_for_review' });
  return rows.length ? done(`🔓 Pieza reabierta${e.actor_name ? ` por ${e.actor_name}` : ''}: te reenvío la propuesta.`, { changed: true, resend: true }) : stale();
}
if (e.action === 'discard') {
  const rows = await patch(filter, { status: 'discarded' });
  return rows.length ? done('❌ Contenido descartado.', { changed: true }) : stale();
}
if (e.action === 'edit') {
  // force_reply abre la respuesta; el router reconoce la respuesta por «Contenido: <uuid>» del texto de este mensaje
  await tg('sendMessage', { chat_id: e.chat_id, text: `✏️ Escribe el nuevo caption para Instagram respondiendo a este mensaje.\n\nContenido: ${id}`,
    reply_markup: { force_reply: true, input_field_placeholder: 'Nuevo caption' } });
  return done(null, { prompted: true });
}
if (e.action === 'editreply') {
  if (e.reply_text.length < 1) return done('⚠️ El caption no puede estar vacío. Vuelve a tocar «Editar».', { reason: 'caption vacío' });
  // El texto del aprobador solo se guarda como dato (cuerpo JSON); no se usa en ningún prompt (OWASP A03)
  const rows = await patch(filter, { caption_instagram: e.reply_text });
  return rows.length ? done('✅ Caption de Instagram actualizado.', { changed: true, resend: true }) : stale();
}
// regenerate: solo imágenes; la URL de descarga lleva el token del bot, se arma aquí y no se guarda
if (item.asset_type !== 'image' || !String(item.raw_asset_url ?? '').startsWith('telegram:')) return done('⚠️ Solo puedo regenerar imágenes recibidas por Telegram.', { reason: 'no es una imagen de Telegram' });
const r = await this.helpers.httpRequest({ method: 'GET', url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/getFile`,
  qs: { file_id: item.raw_asset_url.slice('telegram:'.length) }, json: true, ignoreHttpStatusErrors: true, timeout: 30000 });
if (!r?.ok || !/^[A-Za-z0-9_\/.-]+$/.test(String(r.result?.file_path ?? ''))) return done('⚠️ No pude volver a leer la imagen original. Envíala de nuevo al bot.', { reason: 'getFile falló' });
const rows = await patch(filter, { status: 'processing' });
if (!rows.length) return stale();
return [{ json: { then: 'regenerate', text: null, changed: true, content_item_id: id, notes: item.notes ?? '', image_url: `https://api.telegram.org/file/bot${$env.TELEGRAM_BOT_TOKEN}/${r.result.file_path}` } }];
};

const out = await run();
const r = out[0].json;
// Sin item no hay a qué colgar la fila (clave foránea). Si el registro falla no se bloquea la acción: queda en error_log y se avisa
if (!r.missing) {
  const applied = Boolean(r.changed || r.prompted);
  const row = { content_item_id: id, action: e.action, outcome: applied ? 'applied' : 'ignored',
    actor_telegram_id: e.actor_id ? Number(e.actor_id) : null, actor_name: e.actor_name || null,
    detail: ['editreply', 'objectreply'].includes(e.action) ? e.reply_text : (applied ? null : (r.reason ?? null)) };
  try {
    await this.helpers.httpRequest({ method: 'POST', url: `${base}/review_actions`, headers: { ...headers, Prefer: 'return=minimal' }, body: row, json: true, timeout: 30000 });
    r.logged = true;
  } catch (err) {
    r.logged = false;
    const message = String(err?.message ?? err).slice(0, 500);
    try { await this.helpers.httpRequest({ method: 'POST', url: `${base}/error_log`, headers: { ...headers, Prefer: 'return=minimal' }, json: true, timeout: 30000,
      body: { workflow: '31-atender-revision', content_item_id: id, error_type: 'review_actions_insert', error_message: message } }); } catch (err2) { /* sin más recursos */ }
  }
}
return out;

const tg = (method, body) => this.helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/${method}`, body, json: true, timeout: 30000 });
// Cuenta el resultado. Viene de «Aplicar acción» (con text) o de WF20 al regenerar (sin text)
const r = $input.first().json;
const a = $('Aplicar acción').first().json;
const e = $('Interpretar').first().json;
let text = a.text;
if (a.then === 'regenerate') {
  text = r.ok === true && r.status === 'ready_for_review'
    ? '🔄 Listo: generé una nueva propuesta.'
    : '⚠️ No pude regenerar la propuesta. El administrador ya tiene el aviso y se reintenta si fue un problema temporal.';
}
if (text) { try { await tg('sendMessage', { chat_id: e.chat_id, text }); } catch (err) { /* no bloquea */ } }
return [{ json: { ok: r.ok !== false, action: e.action, content_item_id: e.content_item_id, changed: Boolean(a.changed), message_sent: Boolean(text) } }];

const tg = (method, body) => this.helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/${method}`, body, json: true, timeout: 30000 });
// Cualquier excepción: fila en error_log, aviso al administrador y al aprobador. El estado del item no se toca
const raw = $input.first().json;
const mask = (s) => String(s).replace(/bot\d+:[A-Za-z0-9_-]+/g, 'bot***');
const message = mask(raw.error?.message ?? raw.error ?? raw.message ?? 'Error sin mensaje').slice(0, 2000);
const error_type = (message.match(/^([a-z_]+):/) ?? [])[1] ?? 'execution_error';
const entrada = $('Entrada').first(0, 0)?.json ?? {};
const itemId = $('Interpretar').isExecuted ? ($('Interpretar').first(0, 0)?.json?.content_item_id ?? null) : null;
const key = $env.SUPABASE_SERVICE_ROLE_KEY;
const attempt = async (fn) => { try { await fn(); return true; } catch (err) { return false; } };
const logged = await attempt(() => this.helpers.httpRequest({ method: 'POST', url: `${$env.SUPABASE_URL}/rest/v1/error_log`, json: true, timeout: 30000,
  headers: { apikey: key, Authorization: `Bearer ${key}`, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
  body: { workflow: '31-atender-revision', content_item_id: itemId, error_type, error_message: message } }));
await attempt(() => tg('sendMessage', { chat_id: $env.TELEGRAM_ADMIN_CHAT_ID, text: `⚠️ 31 - Atender revisión: ${message.slice(0, 500)}\nEjecución: ${$execution.id}` }));
if (/^-?\d{1,20}$/.test(String(entrada.chat_id ?? ''))) await attempt(() => tg('sendMessage', { chat_id: entrada.chat_id, text: '⚠️ No pude completar esa acción. Ya avisé al administrador.' }));
return [{ json: { ok: false, error_type, error_message: message, content_item_id: itemId, logged } }];
